import os, h5py
root='/app/data'
files=[]
for dp, dn, fn in os.walk(root):
    for f in fn:
        if f.endswith('.nwb'):
            files.append(os.path.join(dp,f))
files=sorted(files)
for exclude_ignore in [False, True]:
    keep=0
    for f in files:
        with h5py.File(f,'r') as h5:
            tr=h5['intervals']['trials']
            def dec(arr):
                out=[]
                for x in arr:
                    if isinstance(x, bytes): out.append(x.decode())
                    elif hasattr(x, 'decode'): out.append(x.decode())
                    else: out.append(str(x))
                return out
            outcome=dec(tr['outcome'][:])
            early=dec(tr['early_lick'][:])
            instr=dec(tr['trial_instruction'][:])
            photo=dec(tr['photostim_duration'][:])
            ctrl=[i for i,(p,e) in enumerate(zip(photo,early)) if p=='N/A' and e!='early']
            if exclude_ignore:
                ctrl=[i for i in ctrl if outcome[i] != 'ignore']
            if not ctrl:
                continue
            hits=[i for i in ctrl if outcome[i]=='hit']
            perf=len(hits)/len(ctrl)
            left_hits=sum(1 for i in hits if instr[i]=='left')
            right_hits=sum(1 for i in hits if instr[i]=='right')
            keep += int(perf>0.65 and left_hits>=50 and right_hits>=50)
    print('exclude_ignore', exclude_ignore, 'keep_sessions', keep)
