import os,h5py,statistics
root='/app/data'
files=[]
for dp,dn,fn in os.walk(root):
    for f in fn:
        if f.endswith('.nwb'):
            files.append(os.path.join(dp,f))
files=sorted(files)
# sessions with any class good
keep=[]
for f in files:
    with h5py.File(f,'r') as h5:
        vals=[]
        for x in h5['units']['classification'][:]:
            if isinstance(x, bytes): vals.append(x.decode())
            elif hasattr(x,'decode'): vals.append(x.decode())
            else: vals.append(str(x))
        if 'good' in vals:
            keep.append(f)
print('keep173', len(keep))
for label, fset in [('all174', files), ('keep173', keep)]:
    trial_all=[]; trial_noearly=[]; trial_noearly_noignore=[]
    for f in fset:
        with h5py.File(f,'r') as h5:
            tr=h5['intervals']['trials']
            def dec(arr):
                out=[]
                for x in arr:
                    if isinstance(x, bytes): out.append(x.decode())
                    elif hasattr(x,'decode'): out.append(x.decode())
                    else: out.append(str(x))
                return out
            outcome=dec(tr['outcome'][:]); early=dec(tr['early_lick'][:])
            trial_all.append(len(outcome))
            trial_noearly.append(sum(e!='early' for e in early))
            trial_noearly_noignore.append(sum((e!='early') and (o!='ignore') for e,o in zip(early,outcome)))
    print(label, 'mean_all', round(statistics.mean(trial_all),3), 'mean_noearly', round(statistics.mean(trial_noearly),3), 'mean_noearly_noignore', round(statistics.mean(trial_noearly_noignore),3))
