        outcome_map = {'ignore': 0, 'miss': 1, 'hit': 2}
        early_map = {'no early': 0, 'early': 1}
        outcome = np.array([outcome_map[x] for x in outcome_text], dtype=np.int64)
        early = np.array([early_map[x] for x in early_text], dtype=np.int64)

