            edges_abs = go + BIN_EDGES_REL
            if edges_abs[0] < tongue_timestamps[0] or edges_abs[-1] > tongue_timestamps[-1]:
                continue
            sample_start = last_event_before(sample_start_times, float(trial_start[i]), go)
            if sample_start is None:
                continue

