                abs_centers = go + BIN_CENTERS_REL
                input_arr[1] = ((abs_centers >= stim_on) & (abs_centers < stim_off)).astype(np.float32)

            tongue_disc = discretize_tongue_bins(
                tongue_timestamps,
                tongue_xy,
                tongue_visible_mask,
                tongue_q40,
                tongue_q60,
                edges_abs,
            )
            output_arr = np.empty((4, NBINS), dtype=np.int64)
            output_arr[0] = choice[i]
            output_arr[1] = outcome[i]
            output_arr[2] = early[i]
            output_arr[3] = tongue_disc

            kept_counter += 1
            if kept_counter == target_kept_idx:
                return {
                    'raw_trial_idx': i,
                    'neural': neural,
                    'input': input_arr,
                    'output': output_arr,
                }
    raise IndexError('target kept trial not found')

