session_ids = [get_session_id(p) for p in paths]
with open('/app/converted_data.pkl', 'rb') as f:
    data = pickle.load(f)

# pick representative checks from converted data
neural_check = (0, 10)
input_check = None
output_check = None
for si, sess in enumerate(data['input']):
