    conv = data[kind][si][ti]
    same = np.allclose(raw[kind], conv)
    maxdiff = float(np.max(np.abs(raw[kind].astype(np.float64) - conv.astype(np.float64))))
    print(kind, 'session', sid, 'converted_trial', ti, 'raw_trial', raw['raw_trial_idx'], 'allclose', same, 'maxdiff', maxdiff)
